#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
MFP-3 ONE FILE v1.15 — REGIME-GATED FUSION
==========================================

Mantiene todo v1.14 y añade una capa adaptativa adicional.

Idea:
- v1.7-FROZEN sigue siendo el motor principal.
- Synergy actúa como defensa.
- Su peso NO tiene por qué ser constante.
- Cada mes se determina el régimen usando sólo datos anteriores.
- Se busca históricamente qué mezcla funcionó mejor en regímenes semejantes.
- Si no hay suficiente evidencia, se vuelve prudentemente hacia v1.7.

Regímenes:
- RISK_ON
- NEUTRAL
- RISK_OFF

Variables:
- retorno benchmark 21/63/126 sesiones
- volatilidad 21/63
- drawdown benchmark
- drawdown v1.7
- ventaja reciente v1.7 vs Synergy
- correlación v1.7/Synergy

Todo es walk-forward y usa únicamente pasado.

No modifica v1.7-FROZEN.
No ejecuta operaciones reales.

Uso:
    py mfp3_onefile_v1_15.py
    py mfp3_onefile_v1_15.py --regime
    py mfp3_onefile_v1_15.py --install
    py mfp3_onefile_v1_15.py --status
"""

from __future__ import annotations

import argparse
import base64
import json
import os
import subprocess
import sys
import zlib
from datetime import datetime, timezone
from pathlib import Path

import numpy as np
import pandas as pd

V114_B64 = """"""

def embedded_source(blob: str) -> str:
    return zlib.decompress(base64.b64decode(blob)).decode("utf-8")

V114_SOURCE = embedded_source(V114_B64)

ROOT = Path(".")
LAB = ROOT / "mfp3_regime_fusion_lab"
LAB.mkdir(exist_ok=True)

FUSION_DAILY_114 = ROOT / "mfp3_fusion_lab" / "fusion_daily.csv"

OUT_DAILY = LAB / "regime_fusion_daily.csv"
OUT_DECISIONS = LAB / "regime_fusion_decisions.csv"
OUT_METRICS = LAB / "regime_fusion_metrics.csv"
OUT_STATE = LAB / "regime_fusion_state.json"

INITIAL_CAPITAL = 10_000_000.0

# Weight is allocation to v1.7. Rest goes to Synergy.
V17_WEIGHTS = [0.50, 0.60, 0.67, 0.75, 0.85, 0.93, 1.00]

TRAIN_WINDOWS = [252, 504, 756]
MIN_REGIME_DAYS = 80
MIN_TRAIN_DAYS = 252

# avoid excessive switching
HYSTERESIS = 0.07

# shrink regime-specific target toward v1.7 when sample is small
REGIME_SHRINK_K = 180.0

TASK_NAME = "MFP3_ONEFILE_V115_DAILY"
RUN_EVERY_DAYS = 14

# ---------------------------------------------------------------------
# v1.14 runner
# ---------------------------------------------------------------------

def run_v114(args):
    old = sys.argv[:]
    try:
        sys.argv = ["mfp3_v114_embedded.py"]
        if args.full:
            sys.argv.append("--full")

        g = {
            "__name__": "mfp3_v114_embedded",
            "__file__": "<embedded:v1.14>",
            "__builtins__": __builtins__,
        }

        exec(
            compile(V114_SOURCE, g["__file__"], "exec"),
            g,
            g,
        )
        g["main"]()
    finally:
        sys.argv = old

# ---------------------------------------------------------------------
# Scheduler
# ---------------------------------------------------------------------

def install_this_file():
    if os.name != "nt":
        raise SystemExit("--install sólo funciona en Windows.")

    script = str(Path(__file__).resolve())
    python = str(Path(sys.executable).resolve())
    action = f'"{python}" "{script}"'

    p = subprocess.run(
        [
            "schtasks", "/Create",
            "/TN", TASK_NAME,
            "/TR", action,
            "/SC", "DAILY",
            "/ST", "18:30",
            "/F",
        ],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )

    if p.returncode != 0:
        print(p.stdout)
        print(p.stderr)
        raise SystemExit("No se pudo instalar la tarea.")

    print(p.stdout.strip())
    print("Instalado: v1.15 se ejecutará diariamente a las 18:30.")

def uninstall_this_file():
    if os.name != "nt":
        raise SystemExit("--uninstall sólo funciona en Windows.")

    p = subprocess.run(
        ["schtasks", "/Delete", "/TN", TASK_NAME, "/F"],
        capture_output=True,
        text=True,
        encoding="utf-8",
        errors="replace",
    )
    print((p.stdout or p.stderr).strip())

# ---------------------------------------------------------------------
# Metrics
# ---------------------------------------------------------------------

def perf(ret):
    r = pd.Series(ret).fillna(0.0)

    if len(r) == 0:
        return {
            "total_return": 0.0,
            "cagr": 0.0,
            "sharpe": 0.0,
            "max_drawdown": 0.0,
            "ann_vol": 0.0,
        }

    curve = (1 + r).cumprod()
    total = float(curve.iloc[-1] - 1.0)
    years = max(len(r) / 252.0, 1 / 252.0)
    cagr = float(curve.iloc[-1] ** (1 / years) - 1.0)
    vol = float(r.std() * np.sqrt(252))
    sharpe = float(r.mean() * 252 / vol) if vol > 1e-12 else 0.0
    dd = curve / curve.cummax() - 1.0

    return {
        "total_return": total,
        "cagr": cagr,
        "sharpe": sharpe,
        "max_drawdown": float(dd.min()),
        "ann_vol": vol,
    }

def utility(ret):
    p = perf(ret)

    # balance return, Sharpe and drawdown
    u = (
        p["sharpe"]
        + 0.45 * p["cagr"]
        - 0.60 * abs(p["max_drawdown"])
    )

    return u, p

# ---------------------------------------------------------------------
# Load v1.14 aligned return set
# ---------------------------------------------------------------------

def load_base():
    if not FUSION_DAILY_114.exists():
        raise RuntimeError(
            "Falta mfp3_fusion_lab/fusion_daily.csv. "
            "Ejecuta primero v1.14."
        )

    x = pd.read_csv(
        FUSION_DAILY_114,
        index_col=0,
        parse_dates=True,
    ).sort_index()

    required = {
        "v17_ret",
        "synergy_ret",
        "benchmark_ret",
    }

    missing = required - set(x.columns)

    if missing:
        raise RuntimeError(
            f"Faltan columnas requeridas: {missing}"
        )

    return x

# ---------------------------------------------------------------------
# Regime features
# ---------------------------------------------------------------------

def drawdown_series(ret):
    curve = (1 + ret.fillna(0.0)).cumprod()
    return curve / curve.cummax() - 1.0

def rolling_features(x):
    f = pd.DataFrame(index=x.index)

    bm = x["benchmark_ret"].fillna(0.0)
    v17 = x["v17_ret"].fillna(0.0)
    syn = x["synergy_ret"].fillna(0.0)

    for n in [21, 63, 126]:
        f[f"bm_ret_{n}"] = (
            (1 + bm).rolling(n).apply(np.prod, raw=True) - 1
        )
        f[f"v17_ret_{n}"] = (
            (1 + v17).rolling(n).apply(np.prod, raw=True) - 1
        )
        f[f"syn_ret_{n}"] = (
            (1 + syn).rolling(n).apply(np.prod, raw=True) - 1
        )
        f[f"edge_v17_syn_{n}"] = (
            f[f"v17_ret_{n}"] - f[f"syn_ret_{n}"]
        )

    for n in [21, 63]:
        f[f"bm_vol_{n}"] = (
            bm.rolling(n).std() * np.sqrt(252)
        )
        f[f"v17_vol_{n}"] = (
            v17.rolling(n).std() * np.sqrt(252)
        )
        f[f"syn_vol_{n}"] = (
            syn.rolling(n).std() * np.sqrt(252)
        )
        f[f"corr_v17_syn_{n}"] = (
            v17.rolling(n).corr(syn)
        )

    f["bm_dd"] = drawdown_series(bm)
    f["v17_dd"] = drawdown_series(v17)
    f["syn_dd"] = drawdown_series(syn)

    return f

def regime_at(features, dt, history):
    row = features.loc[dt]

    # Use only prior history to form volatility percentile.
    past = features.loc[:dt].iloc[:-1]

    if len(past) < 126:
        return "NEUTRAL"

    vol = float(row.get("bm_vol_21", np.nan))
    bm63 = float(row.get("bm_ret_63", np.nan))
    dd = float(row.get("bm_dd", np.nan))
    v17dd = float(row.get("v17_dd", np.nan))

    hist_vol = pd.to_numeric(
        past["bm_vol_21"],
        errors="coerce",
    ).dropna()

    if len(hist_vol) >= 60:
        q75 = float(hist_vol.quantile(0.75))
        q40 = float(hist_vol.quantile(0.40))
    else:
        q75 = np.nan
        q40 = np.nan

    risk_off = (
        (np.isfinite(bm63) and bm63 < -0.05)
        or (np.isfinite(dd) and dd < -0.08)
        or (np.isfinite(v17dd) and v17dd < -0.10)
        or (
            np.isfinite(vol)
            and np.isfinite(q75)
            and vol > q75
        )
    )

    risk_on = (
        np.isfinite(bm63)
        and bm63 > 0.04
        and np.isfinite(dd)
        and dd > -0.04
        and (
            not np.isfinite(vol)
            or not np.isfinite(q40)
            or vol <= q40
        )
    )

    if risk_off:
        return "RISK_OFF"
    if risk_on:
        return "RISK_ON"
    return "NEUTRAL"

def historical_regimes(features):
    out = pd.Series(
        "NEUTRAL",
        index=features.index,
        dtype=object,
    )

    for i, dt in enumerate(features.index):
        if i < 126:
            continue
        out.loc[dt] = regime_at(
            features,
            dt,
            features.iloc[:i+1],
        )

    return out

# ---------------------------------------------------------------------
# Candidate allocation search
# ---------------------------------------------------------------------

def blended_return(frame, w):
    return (
        float(w) * frame["v17_ret"]
        + (1.0 - float(w)) * frame["synergy_ret"]
    )

def score_weight(frame, w):
    r = blended_return(frame, w)
    u, p = utility(r)

    # tiny preference for v1.7 when otherwise tied
    u -= 0.015 * (1.0 - w)

    return u, p

def select_weight_for_regime(
    history,
    regimes,
    current_regime,
):
    rows = []

    # Global candidates and same-regime candidates both participate.
    for window in TRAIN_WINDOWS:
        base = history.tail(window)

        if len(base) < min(MIN_TRAIN_DAYS, window):
            continue

        rbase = regimes.reindex(base.index)

        same = base[
            rbase == current_regime
        ]

        for w in V17_WEIGHTS:
            global_u, global_p = score_weight(
                base,
                w,
            )

            if len(same) >= MIN_REGIME_DAYS:
                regime_u, regime_p = score_weight(
                    same,
                    w,
                )

                n = len(same)
                reliability = n / (n + REGIME_SHRINK_K)

                # Blend regime utility with global utility.
                score = (
                    reliability * regime_u
                    + (1.0 - reliability) * global_u
                )
            else:
                regime_u = np.nan
                n = len(same)
                reliability = 0.0
                score = global_u

            rows.append({
                "window": window,
                "regime": current_regime,
                "v17_weight": w,
                "score": score,
                "global_utility": global_u,
                "regime_utility": regime_u,
                "same_regime_days": n,
                "reliability": reliability,
                "global_sharpe": global_p["sharpe"],
                "global_drawdown": global_p["max_drawdown"],
            })

    tab = pd.DataFrame(rows)

    if tab.empty:
        return 1.0, tab

    top = tab.sort_values(
        ["score", "global_sharpe"],
        ascending=False,
    ).head(4).copy()

    s = top["score"].to_numpy(dtype=float)
    s = s - np.nanmax(s)

    probs = np.exp(s / 0.08)
    probs = probs / probs.sum()

    top["ensemble_weight"] = probs

    raw_target = float(
        np.sum(
            top["v17_weight"].to_numpy(dtype=float)
            * probs
        )
    )

    # Extra conservative shrinkage toward v1.7.
    reliability = float(
        top["reliability"].max()
    )

    target = (
        reliability * raw_target
        + (1.0 - reliability) * 1.0
    )

    return float(
        np.clip(target, 0.50, 1.0)
    ), top

# ---------------------------------------------------------------------
# Monthly walk-forward regime fusion
# ---------------------------------------------------------------------

def monthly_dates(index):
    s = pd.Series(
        np.arange(len(index)),
        index=index,
    )
    return (
        s.groupby([index.year, index.month])
        .head(1)
        .index
    )

def run_regime_fusion():
    x = load_base()
    features = rolling_features(x)
    regimes = historical_regimes(features)

    firsts = set(
        monthly_dates(x.index)
    )

    weights = pd.Series(
        1.0,
        index=x.index,
        dtype=float,
    )

    current_w = 1.0
    decisions = []

    for i, dt in enumerate(x.index):
        if i < MIN_TRAIN_DAYS:
            weights.loc[dt] = current_w
            continue

        if dt in firsts:
            history = x.iloc[:i]
            hist_regimes = regimes.iloc[:i]
            current_regime = str(
                regimes.loc[dt]
            )

            target, top = select_weight_for_regime(
                history,
                hist_regimes,
                current_regime,
            )

            if abs(target - current_w) >= HYSTERESIS:
                applied = target
            else:
                applied = current_w

            decisions.append({
                "date": dt,
                "regime": current_regime,
                "previous_v17_weight": current_w,
                "target_v17_weight": target,
                "applied_v17_weight": applied,
                "synergy_weight": 1.0 - applied,
                "v17_drawdown": float(
                    features.loc[dt, "v17_dd"]
                ) if pd.notna(
                    features.loc[dt, "v17_dd"]
                ) else np.nan,
                "benchmark_ret_63": float(
                    features.loc[dt, "bm_ret_63"]
                ) if pd.notna(
                    features.loc[dt, "bm_ret_63"]
                ) else np.nan,
                "benchmark_vol_21": float(
                    features.loc[dt, "bm_vol_21"]
                ) if pd.notna(
                    features.loc[dt, "bm_vol_21"]
                ) else np.nan,
                "best_window": (
                    int(top.iloc[0]["window"])
                    if len(top) else np.nan
                ),
                "best_candidate_weight": (
                    float(top.iloc[0]["v17_weight"])
                    if len(top) else np.nan
                ),
                "regime_reliability": (
                    float(top["reliability"].max())
                    if len(top) else 0.0
                ),
            })

            current_w = applied

        weights.loc[dt] = current_w

    out = x.copy()
    out["regime"] = regimes
    out["v17_weight_regime"] = (
        weights.ffill().fillna(1.0)
    )
    out["synergy_weight_regime"] = (
        1.0 - out["v17_weight_regime"]
    )

    out["regime_fusion_ret"] = (
        out["v17_weight_regime"]
        * out["v17_ret"]
        + out["synergy_weight_regime"]
        * out["synergy_ret"]
    )

    out["capital_regime_fusion"] = (
        INITIAL_CAPITAL
        * (1 + out["regime_fusion_ret"]).cumprod()
    )
    out["capital_v17"] = (
        INITIAL_CAPITAL
        * (1 + out["v17_ret"]).cumprod()
    )
    out["capital_synergy"] = (
        INITIAL_CAPITAL
        * (1 + out["synergy_ret"]).cumprod()
    )
    out["capital_benchmark"] = (
        INITIAL_CAPITAL
        * (1 + out["benchmark_ret"]).cumprod()
    )

    # Also compare old v1.14 fusion if available in x.
    rows = [
        {
            "name": "REGIME_GATED_FUSION_CHALLENGER",
            **perf(out["regime_fusion_ret"]),
        },
        {
            "name": "V17_REFERENCE_COMMON_WINDOW",
            **perf(out["v17_ret"]),
        },
        {
            "name": "SYNERGY_REFERENCE_COMMON_WINDOW",
            **perf(out["synergy_ret"]),
        },
        {
            "name": "BENCHMARK_COMMON_WINDOW",
            **perf(out["benchmark_ret"]),
        },
    ]

    if "fusion_ret" in out.columns:
        rows.insert(
            1,
            {
                "name": "V14_ADAPTIVE_FUSION_REFERENCE",
                **perf(out["fusion_ret"]),
            },
        )

    metrics = pd.DataFrame(rows)
    decisions_df = pd.DataFrame(decisions)

    out.to_csv(
        OUT_DAILY,
        encoding="utf-8-sig",
    )
    decisions_df.to_csv(
        OUT_DECISIONS,
        index=False,
        encoding="utf-8-sig",
    )
    metrics.to_csv(
        OUT_METRICS,
        index=False,
        encoding="utf-8-sig",
    )

    OUT_STATE.write_text(
        json.dumps(
            {
                "last_completed_utc":
                    datetime.now(timezone.utc).isoformat(timespec="seconds"),
                "version": "v1.15",
                "latest_regime":
                    str(out["regime"].iloc[-1]),
                "latest_v17_weight":
                    float(out["v17_weight_regime"].iloc[-1]),
                "latest_synergy_weight":
                    float(out["synergy_weight_regime"].iloc[-1]),
            },
            indent=2,
        ),
        encoding="utf-8",
    )

    return out, decisions_df, metrics

# ---------------------------------------------------------------------
# Cadence
# ---------------------------------------------------------------------

def regime_due(force=False):
    if force or not OUT_STATE.exists():
        return True

    try:
        s = json.loads(
            OUT_STATE.read_text(
                encoding="utf-8"
            )
        )
        last = pd.Timestamp(
            s["last_completed_utc"]
        )

        if last.tzinfo is None:
            last = last.tz_localize("UTC")
        else:
            last = last.tz_convert("UTC")

        return (
            pd.Timestamp.now(tz="UTC") - last
        ).days >= RUN_EVERY_DAYS

    except Exception:
        return True

# ---------------------------------------------------------------------
# Main
# ---------------------------------------------------------------------

def main():
    p = argparse.ArgumentParser()
    p.add_argument(
        "--regime",
        action="store_true",
    )
    p.add_argument(
        "--install",
        action="store_true",
    )
    p.add_argument(
        "--uninstall",
        action="store_true",
    )
    p.add_argument(
        "--status",
        action="store_true",
    )
    p.add_argument(
        "--full",
        action="store_true",
    )

    args = p.parse_args()

    if args.install:
        install_this_file()
        return

    if args.uninstall:
        uninstall_this_file()
        return

    if args.status:
        print("\nMFP-3 v1.15 STATUS")
        print(
            "Regime Fusion Lab:",
            LAB.resolve(),
        )
        print(
            "Regime due:",
            regime_due(False),
        )
        print(
            "Metrics:",
            OUT_METRICS.exists(),
        )
        print(
            "Decisions:",
            OUT_DECISIONS.exists(),
        )
        return

    print("\n" + "=" * 98)
    print("MFP-3 ONE FILE v1.15 — REGIME-GATED FUSION")
    print("=" * 98)

    run_v114(args)

    if regime_due(args.regime):
        print(
            "\n[v1.15] Aprendiendo cuándo activar Synergy "
            "según régimen..."
        )

        out, decisions, metrics = run_regime_fusion()

        print("\n" + "=" * 98)
        print("REGIME-GATED FUSION — RESULTADO")
        print("=" * 98)

        with pd.option_context(
            "display.max_columns",
            None,
            "display.width",
            195,
        ):
            print(metrics)

        print(
            "\nCapital Regime Fusion:",
            f"${out['capital_regime_fusion'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital v1.7:",
            f"${out['capital_v17'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital Synergy:",
            f"${out['capital_synergy'].iloc[-1]:,.0f} CLP"
        )
        print(
            "Capital Benchmark:",
            f"${out['capital_benchmark'].iloc[-1]:,.0f} CLP"
        )

        print("\nEstado aprendido actual:")
        print(
            "  Régimen:",
            out["regime"].iloc[-1]
        )
        print(
            "  v1.7:",
            f"{out['v17_weight_regime'].iloc[-1]:.1%}"
        )
        print(
            "  Synergy:",
            f"{out['synergy_weight_regime'].iloc[-1]:.1%}"
        )

        if len(decisions):
            print("\nÚltimas decisiones por régimen:")
            with pd.option_context(
                "display.max_columns",
                None,
                "display.width",
                200,
            ):
                print(
                    decisions.tail(10)
                )

    else:
        print(
            "\n[v1.15] Regime Fusion Lab ya está actualizado. "
            "Se repite automáticamente cada 14 días."
        )

    print(
        "\nRegime-Gated Fusion sigue siendo Challenger. "
        "La cartera Forward v1.7-FROZEN permanece intacta."
    )

if __name__ == "__main__":
    main()
